import sys
from collections import deque

MAXN = 25
INF = 10007
MAXT = 65
MAXC = 12

# Global variables (will be set in main)
n = 0
k = 0
T1 = []
T2 = []
distZ = [[0]*MAXN for _ in range(MAXN)]
memo = None  # 5D list
dirX = [1, 0, -1, 0]
dirY = [0, 1, 0, -1]
sources = []
sinks = []

class RelabelFlow:
    def __init__(self, N):
        self.N = N
        self.edges = []  # list of (from, to, cap, flow)
        self.adj = [[] for _ in range(N)]
        self.h = [0]*N
        self.inQ = [0]*N
        self.cnt = [0]*(2*N)
        self.ex = [0]*N
        self.q = deque()

    def addEdge(self, u, v, cap):
        self.adj[u].append(len(self.edges))
        self.edges.append([u, v, cap, 0])
        self.adj[v].append(len(self.edges))
        self.edges.append([v, u, 0, 0])
        return self.adj[u][-1]

    def enQueue(self, u):
        if not self.inQ[u] and self.ex[u] > 0:
            self.q.append(u)
            self.inQ[u] = True

    def pushEdge(self, id):
        e = self.edges[id]
        d = min(e[2] - e[3], self.ex[e[0]])
        if d > 0 and self.h[e[0]] > self.h[e[1]]:
            e[3] += d
            self.ex[e[1]] += d
            self.ex[e[0]] -= d
            self.edges[id ^ 1][3] -= d
            self.enQueue(e[1])

    def relabelNode(self, u):
        self.cnt[self.h[u]] -= 1
        self.h[u] = 2 * self.N - 2
        for i in self.adj[u]:
            e = self.edges[i]
            if e[2] > e[3]:
                self.h[u] = min(self.h[u], self.h[e[1]])
        self.cnt[self.h[u] + 1] += 1
        self.h[u] += 1

    def gap(self, height):
        for u in range(self.N):
            if self.h[u] >= height and self.h[u] < self.N:
                self.cnt[self.h[u]] -= 1
                self.h[u] = self.N
                self.cnt[self.N] += 1
                self.enQueue(u)

    def discharge(self, u):
        i = 0
        while self.ex[u] > 0 and i < len(self.adj[u]):
            self.pushEdge(self.adj[u][i])
            i += 1
        if self.ex[u] > 0:
            if self.h[u] < self.N and self.cnt[self.h[u]] < 2:
                self.gap(self.h[u])
            else:
                self.relabelNode(u)
        else:
            if self.q:
                self.q.popleft()
                self.inQ[u] = False

    def maxflow(self, s, t):
        self.h[s] = self.N
        self.inQ[s] = self.inQ[t] = True
        self.cnt[0] = self.N - 1
        self.cnt[self.N] = 1
        for i in self.adj[s]:
            self.ex[s] += self.edges[i][2]
            self.pushEdge(i)
        while self.q:
            self.discharge(self.q[0])
        return self.ex[t]

def computeDist(sx, sy):
    global distZ
    distZ = [[-1]*n for _ in range(n)]
    q = deque()
    distZ[sx][sy] = 0
    q.append((sx, sy))
    while q:
        x, y = q.popleft()
        for d in range(4):
            nx = x + dirX[d]
            ny = y + dirY[d]
            if nx < 0 or nx >= n or ny < 0 or ny >= n:
                continue
            if distZ[nx][ny] != -1:
                continue
            if T2[nx][ny] == 'Y' or T2[nx][ny] == 'Z':
                continue
            distZ[nx][ny] = distZ[x][y] + 1
            q.append((nx, ny))

def can(t, x0, y0, x, y):
    if distZ[x0][y0] < t:
        return 0
    if x0 == x and y0 == y:
        return 1
    if t >= k:
        return 0
    if distZ[x0][y0] <= t:
        return 0
    res = memo[t][x0][y0][x][y]
    if res != -1:
        return res
    for d in range(4):
        nx = x0 + dirX[d]
        ny = y0 + dirY[d]
        if nx < 0 or nx >= n or ny < 0 or ny >= n:
            continue
        if T1[nx][ny] == 'Y' or T1[nx][ny] == 'Z':
            continue
        if can(t + 1, nx, ny, x, y):
            memo[t][x0][y0][x][y] = 1
            return 1
    memo[t][x0][y0][x][y] = 0
    return 0

def main():
    global n, k, T1, T2, sources, sinks, memo
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    T1 = [list(next(it).strip()) for _ in range(n)]
    T2 = [list(next(it).strip()) for _ in range(n)]

    # Find Z in T2
    zx = zy = -1
    for i in range(n):
        for j in range(n):
            if T2[i][j] == 'Z':
                zx, zy = i, j
                break
        if zx != -1:
            break

    computeDist(zx, zy)

    for i in range(n):
        for j in range(n):
            if distZ[i][j] == -1:
                distZ[i][j] = INF

    sources = []
    sinks = []
    for i in range(n):
        for j in range(n):
            c = T1[i][j]
            if c not in ('Z', 'Y', '0'):
                sources.append((i, j))
    for i in range(n):
        for j in range(n):
            c = T2[i][j]
            if c not in ('Z', 'Y', '0'):
                sinks.append((i, j))

    # Initialize memo as 5D list: [MAXT][n][n][n][n] with -1
    # Since n <= 12, we can allocate with MAXC=12 for simplicity
    memo = [[[[[-1 for _ in range(MAXC)] for _ in range(MAXC)] for _ in range(MAXC)] for _ in range(MAXC)] for _ in range(MAXT)]

    S = 0
    T = len(sources) + len(sinks) + 1
    rf = RelabelFlow(T + 1)

    for i, (x, y) in enumerate(sources):
        cap = int(T1[x][y])
        rf.addEdge(S, i + 1, cap)

    for i, (x, y) in enumerate(sinks):
        cap = int(T2[x][y])
        rf.addEdge(len(sources) + i + 1, T, cap)

    for i, (sx, sy) in enumerate(sources):
        for j, (tx, ty) in enumerate(sinks):
            if can(0, sx, sy, tx, ty):
                rf.addEdge(i + 1, len(sources) + j + 1, INF)

    print(rf.maxflow(S, T))

if __name__ == "__main__":
    main()
```
